    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(!c.programOperators(address(this)));

        address beforeRoundImplementation = c.roundImplementation(); if (__ESBMC_reverted()) return;
        address beforeAlloSettings = c.alloSettings(); if (__ESBMC_reverted()) return;
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.create(encodedParameters, ownedBy); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

