pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function _run(bytes memory encodedParameters, address ownedBy) internal {
        vm.assume(!c.programOperators(address(this)));
        address beforeRoundImplementation;
        try c.roundImplementation() returns (address __r) { beforeRoundImplementation = __r; } catch { return; }
        address beforeAlloSettings;
        try c.alloSettings() returns (address __r) { beforeAlloSettings = __r; } catch { return; }
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        bool reverted;
        try c.create(encodedParameters, ownedBy) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.roundImplementation() == beforeRoundImplementation && c.alloSettings() == beforeAlloSettings && c.owner() == beforeOwner);
    }

    function testFuzz_run(bytes memory encodedParameters, address ownedBy) public {
